+  </head>
+  <body>
+    <div id="app"></div>
+
+    <script>
+      const image = {
+        title: "Mountain dusk",
+        details: "Added to your library on May 6, 2026",
+        source:
+          "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80",
+      };
+
+      const Button = ({ className = "", type = "button", label, attributes = "" }) => `
+        <button class="button ${className}" type="${type}" ${attributes}>${label}</button>
+      `;
+
+      const ImagePreview = ({ title, details, source }) => `
+        <section class="preview-card" aria-labelledby="image-title">
+          <div class="image-wrap" role="img" aria-label="${title}" style="background-image: linear-gradient(135deg, rgba(15, 23, 42, 0.34), rgba(15, 23, 42, 0.92)), url('${source}');">
+            <span class="image-badge">Library image</span>
+          </div>
+          <div class="preview-content">
+            <div>
+              <h1 class="preview-title" id="image-title">${title}</h1>
+              <p class="preview-meta">${details}</p>
+            </div>
+            <div class="button-row" aria-label="Image actions">
+              ${Button({ className: "button-secondary", label: "Download" })}
+              ${Button({
+                className: "button-danger trigger",
+                label: "Delete image",
+                attributes: 'aria-haspopup="dialog" aria-controls="delete-dialog"',
+              })}
+            </div>
+          </div>
+        </section>
+      `;
+
+      const DeleteDialog = () => `
+        <div class="modal-root" id="delete-modal" aria-hidden="true">
+          <div class="modal-backdrop" data-close-modal></div>
+          <section
+            class="modal-dialog"
+            id="delete-dialog"
+            role="dialog"
+            aria-modal="true"
+            aria-labelledby="delete-dialog-title"
+            aria-describedby="delete-dialog-description"
+            tabindex="-1"
+          >
+            <button class="modal-close" type="button" data-close-modal>
+              <span aria-hidden="true">&times;</span>
+              <span class="sr-only">Close delete confirmation</span>
+            </button>
+            <div class="modal-icon" aria-hidden="true">!</div>
+            <h2 class="modal-title" id="delete-dialog-title">Delete this image?</h2>
+            <p class="modal-copy" id="delete-dialog-description">
+              This will remove "${image.title}" from your library. This action cannot be undone.
+            </p>
+            <div class="modal-actions">
+              ${Button({
+                className: "button-secondary",
+                label: "Cancel",
+                attributes: "data-close-modal",
+              })}
+              ${Button({ className: "button-danger", label: "Yes, delete image" })}
+            </div>
+          </section>
+        </div>
+      `;
+
+      const App = () => `
+        <main class="app-shell">
+          ${ImagePreview(image)}
+          ${DeleteDialog()}
+        </main>
+      `;
+
+      document.getElementById("app").innerHTML = App();
+
+      const modal = document.getElementById("delete-modal");
+      const dialog = document.getElementById("delete-dialog");
+      const trigger = document.querySelector(".trigger");
+      const closeButtons = document.querySelectorAll("[data-close-modal]");
+      let lastFocusedElement = null;
+
+      const setModalOpen = (isOpen) => {
+        modal.classList.toggle("is-open", isOpen);
+        modal.setAttribute("aria-hidden", String(!isOpen));
+
+        if (isOpen) {
+          lastFocusedElement = document.activeElement;
+          dialog.focus();
+        } else if (lastFocusedElement) {
+          lastFocusedElement.focus();
+        }
+      };
+
+      trigger.addEventListener("click", () => setModalOpen(true));
+
+      closeButtons.forEach((button) => {
+        button.addEventListener("click", () => setModalOpen(false));
+      });
+
+      document.addEventListener("keydown", (event) => {
+        if (event.key === "Escape" && modal.classList.contains("is-open")) {
+          setModalOpen(false);
+        }
+      });
+    </script>
+  </body>
